<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth';import {api} from '../api';import {Plus,Search,ArrowUpRight,FileText,Building2,Calculator,FolderOpen} from 'lucide-vue-next';
const auth=useAuth(),router=useRouter(),files=ref<any[]>([]),borrowers=ref<any[]>([]),error=ref(''),busy=ref(false),creating=ref(false),query=ref(''),filter=ref('all');const form=ref({name:'',reference:'',borrower_id:'',module:'bank',is_demo:false,new_borrower:''});const editable=computed(()=>['owner','admin','underwriter','processor'].includes(auth.membership?.role));const visible=computed(()=>files.value.filter(f=>filter.value==='all'||(filter.value==='archived'?!!f.archived_at:!f.archived_at&&f.module===filter.value)));
async function load(){try{busy.value=true;files.value=(await api('/api/files?organization_id='+auth.orgId+'&q='+encodeURIComponent(query.value))).data;borrowers.value=await api('/api/organizations/'+auth.orgId+'/borrowers')}catch(e:any){error.value=e.message}finally{busy.value=false}}onMounted(load);
async function create(){busy.value=true;error.value='';try{let id=Number(form.value.borrower_id);if(form.value.new_borrower)id=(await api('/api/organizations/'+auth.orgId+'/borrowers','POST',{name:form.value.new_borrower})).id;const f=await api('/api/organizations/'+auth.orgId+'/files','POST',{...form.value,borrower_id:id});router.push('/files/'+f.id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">YOUR REVIEW WORKSPACE</span><h1>A clearer view of every loan.</h1><p class="muted">Manage documents and collaborate securely, from first upload to review.</p></div><button v-if="editable" class="primary" @click="creating=true"><Plus :size="18"/>New loan file</button></div><div class="notice"><span class="badge teal">INTEGRATED REVIEW</span><div><strong>Private originals. Evidence-backed human review.</strong><p>Bank, appraisal and rental APIs are connected. Live-provider and guideline approvals remain explicit release gates.</p></div></div><div class="stat-grid"><article class="stat"><span>Accessible loan files</span><strong>{{files.length}}</strong><small>Only files you are authorized to view</small></article><article class="stat"><span>In review</span><strong>{{files.filter(f=>f.status==='in_review').length}}</strong><small>Across your accessible files</small></article><article class="stat"><span>Fictional demo files</span><strong>{{files.filter(f=>f.is_demo).length}}</strong><small>Separate sample analysis action</small></article></div><div class="module-grid"><article v-for="m in [{id:'bank',name:'Bank Statement Income & Integrity',icon:FileText,text:'Personal & business · 12 / 24 months'},{id:'appraisal',name:'Appraisal Review',icon:Building2,text:'Property, comps, source evidence & findings'},{id:'dscr',name:'Rental Income / DSCR',icon:Calculator,text:'Confirmed rents, decimal DSCR/LTV & revisions'}]" class="module-card"><component :is="m.icon" :size="25"/><h3>{{m.name}}</h3><p>{{m.text}}</p><button class="text-button" @click="filter=m.id">View files <ArrowUpRight :size="16"/></button></article></div><div class="section-heading"><h2>Loan files</h2><form class="search" @submit.prevent="load"><Search :size="17"/><input aria-label="Search loan files" v-model="query" placeholder="Search file name…"/><button>Search</button></form></div><div class="tabs"><button v-for="[id,label] in [['all','All accessible'],['bank','Bank statements'],['appraisal','Appraisals'],['dscr','Rental / DSCR'],['archived','Archived']]" :class="{active:filter===id}" @click="filter=id">{{label}}</button></div><p class="alert error" role="alert" v-if="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>Loan file / borrower</th><th>Module</th><th>Status</th><th>Data</th><th></th></tr></thead><tbody><tr v-for="file in visible" :key="file.id"><td><RouterLink :to="'/files/'+file.id" class="file-link">{{file.name}}</RouterLink><small>{{file.borrower?.name}} · {{file.reference||'No reference'}}</small></td><td>{{file.module==='bank'?'Bank statement':file.module==='dscr'?'Rental / DSCR':'Appraisal'}}</td><td><span class="badge">{{file.archived_at?'Archived':file.status.replace('_',' ')}}</span></td><td><span :class="['badge',file.is_demo?'amber':'teal']">{{file.is_demo?'Fictional demo':'Upload workspace'}}</span></td><td><RouterLink :to="'/files/'+file.id" aria-label="Open file"><ArrowUpRight :size="18"/></RouterLink></td></tr></tbody></table><div class="empty-state" v-if="!busy&&!visible.length"><FolderOpen :size="40"/><h3>Your next review starts here.</h3><p>Create a loan file and add fictional source documents. Sample analysis is optional and separate.</p><button v-if="editable" class="primary" @click="creating=true">Create your first file</button></div><p v-if="busy" class="empty-state" role="status">Loading files…</p></div></section><div v-if="creating" class="modal-backdrop" @click.self="creating=false"><section class="modal" v-focus-trap="()=>creating=false" role="dialog" aria-modal="true" aria-labelledby="create-title"><h2 id="create-title">Create a loan file</h2><form class="form-stack" @submit.prevent="create"><label>File name<input v-model="form.name" required maxlength="150"/></label><label>Reference<input v-model="form.reference" maxlength="80"/></label><label>Existing borrower<select v-model="form.borrower_id"><option value="">Select borrower</option><option v-for="b in borrowers" :value="b.id">{{b.name}}</option></select></label><label>Or create a fictional borrower<input v-model="form.new_borrower" placeholder="Fictional borrower name" maxlength="120"/></label><label>Primary module<select v-model="form.module"><option value="bank">Bank Statement Income & Integrity</option><option value="appraisal">Appraisal Review</option><option value="dscr">Rental Income / DSCR</option></select></label><label class="check"><input type="checkbox" v-model="form.is_demo"/>This is a fictional demo file (enables sample analysis)</label><p class="micro">Never upload real financial documents in this development environment.</p><p class="error" v-if="error">{{error}}</p><div class="actions"><button type="button" @click="creating=false">Cancel</button><button class="primary" :disabled="busy">Create file</button></div></form></section></div></template>
